-- Tags every bank question with its skill and step (see 016_skills.sql and
-- lib/skills.ts). Produced by two independent teams of tagging agents who
-- each tagged all 3,150 questions without seeing the other team's tags; they
-- agreed on the skill for 2,839 (90%) and the other 311 were settled by hand.
-- Step: both teams' 1-3 scores were summed and ranked within each level and
-- category, roughly the easiest quarter -> 1 and the hardest quarter -> 3.
-- Step is a rough hint (the teams gave the exact same step 64% of the time);
-- skill is the reliable part. Update only - no rows added or removed.
